prices = {"apple": 50, "banana": 70}
empty = {}
print(prices)

prices = {"apple": 50, "banana": 70}
print(prices["apple"])   # 50
print(prices["kiwi"])     # error!

prices = {"apple": 50}
print(prices.get("kiwi"))       # None
print(prices.get("kiwi", 0))    # 0 — the default

prices = {"apple": 50, "banana": 70}
for name, price in prices.items():
    print(name, price)

words = ["yes", "no", "yes"]
counts = {}
for w in words:
    counts[w] = counts.get(w, 0) + 1
print(counts)    # {'yes': 2, 'no': 1}

d = {}
d[(1, 2)] = "cell"    # a tuple is fine
d[[1, 2]] = "error"   # TypeError: unhashable

prices = {"apple": 50}
print(prices["kiwi"])        # KeyError — use get
for k in prices:
    prices["new"] = 1       # RuntimeError: size changed
